items.web_code:
output('Hello Python!');
output('안녕하세요!');
output('UTTEC 바이브 코딩!');

let name = '학생';
output(`${name}님, 환영합니다!`);

output(`1 + 2 = ${1 + 2}`);
output(`10 * 5 = ${10 * 5}`);

let lastShake = 0;
const diceEmoji = ['⚀','⚁','⚂','⚃','⚄','⚅'];

output('스마트폰을 흔들어보세요!');
output('');

function handleMotion(event) {
  const a = event.accelerationIncludingGravity || event.acceleration;
  if (!a) return;
  const total = Math.abs(a.x) + Math.abs(a.y) + Math.abs(a.z);
  const now = Date.now();
  if (total > 20 && now - lastShake > 1000) {
    lastShake = now;
    const dice = Math.floor(Math.random() * 6) + 1;
    clearOutput();
    setBigText(diceEmoji[dice-1]);
    output('주사위: ' + dice);
    vibrate(200);
  }
}

if (addMotionListener(handleMotion)) {
  output('가속도 센서 활성화!');
} else {
  output('센서를 지원하지 않습니다. 앱에서 실행해주세요.');
}

output('SOS 모스부호 전송 시작!');
output('');

const dot = 200, dash = 600, gap = 200, letterGap = 600;

// SOS 순차 실행
const steps = [
  {type:'dot',sym:'·'},{type:'gap'},{type:'dot',sym:'·'},{type:'gap'},{type:'dot',sym:'·'},
  {type:'letterGap',sym:'  '},
  {type:'dash',sym:'—'},{type:'gap'},{type:'dash',sym:'—'},{type:'gap'},{type:'dash',sym:'—'},
  {type:'letterGap',sym:'  '},
  {type:'dot',sym:'·'},{type:'gap'},{type:'dot',sym:'·'},{type:'gap'},{type:'dot',sym:'·'}
];

let morse = '';
let i = 0;

function playNext() {
  if (i >= steps.length) {
    output('');
    output('SOS 전송 완료!');
    return;
  }
  const s = steps[i];
  if (s.sym) morse += s.sym;

  if (s.type === 'dot') {
    vibrate(dot);
    updateOutput(1, '모스부호: ' + morse);
    setTimeout(playNext, dot + gap);
  } else if (s.type === 'dash') {
    vibrate(dash);
    updateOutput(1, '모스부호: ' + morse);
    setTimeout(playNext, dash + gap);
  } else if (s.type === 'gap') {
    setTimeout(playNext, 50);
  } else {
    setTimeout(playNext, letterGap);
  }
  i++;
}
playNext();

output('카메라를 준비합니다...');

const resultArea = document.getElementById('resultArea');

// input[type=file]로 카메라 접근 (WebView 호환)
const fileInput = document.createElement('input');
fileInput.type = 'file';
fileInput.accept = 'image/*';
fileInput.capture = 'environment';
fileInput.style.display = 'none';

const captureBtn = document.createElement('button');
captureBtn.textContent = '📸 카메라 열기';
captureBtn.style.cssText = 'display:block;margin:8px auto;padding:14px 36px;background:#2563EB;color:white;border:none;border-radius:10px;font-size:16px;cursor:pointer;';

resultArea.appendChild(captureBtn);
resultArea.appendChild(fileInput);

captureBtn.onclick = () => fileInput.click();

fileInput.onchange = (e) => {
  const file = e.target.files[0];
  if (!file) return;

  const reader = new FileReader();
  reader.onload = (ev) => {
    const img = document.createElement('img');
    img.src = ev.target.result;
    img.style.cssText = 'width:100%;max-width:320px;border-radius:12px;margin:8px 0;';
    resultArea.appendChild(img);
    output('촬영 완료! (' + file.name + ', ' + (file.size/1024).toFixed(0) + 'KB)');
    vibrate(100);
  };
  reader.readAsDataURL(file);
};

output('촬영 버튼을 눌러주세요!');

const canvas = document.createElement('canvas');
canvas.width = 300; canvas.height = 300;
canvas.style.cssText = 'display:block;margin:8px auto;border:2px solid #334155;border-radius:12px;background:#0F172A;';
document.getElementById('resultArea').appendChild(canvas);
const ctx = canvas.getContext('2d');

let bx = 150, by = 150;
const br = 12;
let score = 0;
let tx = Math.random()*260+20, ty = Math.random()*260+20;

output('스마트폰을 기울여서 빨간 공을 움직이세요!');
output('노란 목표물을 잡으세요!');

function draw() {
  ctx.fillStyle = '#0F172A';
  ctx.fillRect(0, 0, 300, 300);
  ctx.beginPath();
  ctx.arc(tx, ty, 10, 0, Math.PI*2);
  ctx.fillStyle = '#F59E0B';
  ctx.fill();
  ctx.beginPath();
  ctx.arc(bx, by, br, 0, Math.PI*2);
  ctx.fillStyle = '#EF4444';
  ctx.fill();
  ctx.fillStyle = 'white';
  ctx.font = '14px sans-serif';
  ctx.fillText('Score: ' + score, 10, 20);
  if (Math.hypot(bx-tx, by-ty) < 22) {
    score++;
    tx = Math.random()*260+20;
    ty = Math.random()*260+20;
    vibrate(100);
    updateOutput(0, '기울여서 공을 움직이세요! Score: ' + score);
  }
}

function handleOrientation(e) {
  let x = e.gamma || 0;
  let y = e.beta || 0;
  bx += x * 0.3;
  by += (y - 45) * 0.3;
  bx = Math.max(br, Math.min(300-br, bx));
  by = Math.max(br, Math.min(300-br, by));
}

if (addOrientationListener(handleOrientation)) {
  output('자이로 센서 활성화!');
} else {
  output('센서를 지원하지 않습니다. 앱에서 실행해주세요.');
}

setInterval(draw, 30);
